'use strict';
const $=id=>document.getElementById(id), names={pulse:'Switchboard',bloom:'Room to Grow'}, VERSION='1.0.1', REACTION_GRACE=.45;
let persistent=true,db,stored=null;
try{stored=localStorage.getItem('arcade-lab-v1')}catch{persistent=false}
