const localDay=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
let visit;try{visit=sessionStorage.getItem('arcade-lab-visit');if(!visit){visit=crypto.randomUUID();sessionStorage.setItem('arcade-lab-visit',visit)}}catch{visit=crypto.randomUUID()}
if(!db.visits.some(v=>v.id===visit)){db.visits.push({id:visit,at:new Date().toISOString(),day:localDay()});save()}
const cards=document.querySelector('.cards');db.order.forEach(k=>cards.append(document.querySelector(`[data-game="${k}"]`)));
let screen='home',game=null,state=null,running=false,paused=false,record=null,lastGame=null,keys={left:false,right:false},held=false,pointer={x:420,y:250},lastFrame=0;
const canvas=$('canvas'),ctx=canvas.getContext('2d'),W=840,H=500;
function show(which){if(which==='home')syncStart();screen=which;['home','play','summary','results'].forEach(k=>$(k).hidden=k!==which);$('resultsButton').hidden=which==='play';window.scrollTo(0,0)}
function clearInput(){keys.left=keys.right=false;held=false;if(state?.active)settle()}
function openGame(k,replay=false){game=k;lastGame=k;running=false;paused=false;record=null;clearInput();state=null;show('play');$('gameName').textContent=names[k];$('scoreLabel').textContent=k==='pulse'?'SCORE':'SPACE CLAIMED';$('score').textContent='0';$('time').textContent='60';$('rule').textContent='Three mistakes. One minute.';$('overlay').hidden=false;$('overlayLabel').textContent='HOW TO PLAY';$('overlayTitle').textContent=names[k];$('overlayText').textContent=k==='pulse'?'Four microgames, switching every six seconds. Catch stars, dodge blocks, pass gaps, and move only on green. Use ← → or the buttons below. Three mistakes end the round.':'Hold anywhere in free space to grow a circle. Release before a moving coral ball hits it. Settled circles are safe. Claim 40% to win. Three hits end the round.';$('go').textContent='Start 60-second round →';$('go').onclick=()=>start(replay);$('touchControls').hidden=k!=='pulse';$('controls').textContent=k==='pulse'?'← → / A D / touch buttons to move · Read the new rule every six seconds · Esc to pause':'Mouse or touch: hold to grow, release to settle · Keyboard: arrows to position, Space to grow · Esc to pause';$('pause').textContent='Pause ⏸';drawIdle()}
function start(replay){const previous=db.rounds.filter(r=>r.game===game);record={id:crypto.randomUUID(),version:VERSION,participant:db.participant,visit,day:localDay(),game,assignedOrder:[...db.order],startedAt:new Date().toISOString(),voluntaryReplay:previous.some(r=>r.status==='completed'),status:'started',activeSeconds:0,score:0};db.rounds.push(record);save();state={t:0,lives:3,score:0,flash:0,px:420,task:-1,taskTime:0,objects:[],spawn:0,survival:0,stopTick:-1,balls:[],active:null,enemies:[{x:110,y:120,vx:145,vy:104,r:11},{x:710,y:360,vx:-130,vy:-132,r:11},{x:560,y:100,vx:-85,vy:160,r:11}],blocked:false};pointer={x:420,y:250};held=false;keys.left=keys.right=false;running=true;paused=false;$('overlay').hidden=true;canvas.focus();lastFrame=performance.now()}
function finish(reason){if(!record||!running)return;running=false;held=false;state.active=null;record.status=reason==='abandoned'?'abandoned':'completed';record.reason=reason;record.activeSeconds=+state.t.toFixed(2);record.score=game==='pulse'?Math.floor(state.score):+coverage().toFixed(1);record.endedAt=new Date().toISOString();save();show('summary');$('endTitle').textContent=reason==='abandoned'?'Round left early.':reason==='win'?'Room, beautifully claimed.':state.lives<=0?'Out of chances.':'Time well played.';$('endText').textContent=`${names[game]} · ${game==='pulse'?`${record.score} points`:`${record.score}% claimed`} · ${Math.round(state.t)} seconds of active play.`;$('replay').textContent=`Replay ${names[game]} ↻`;$('other').textContent=`Try ${names[game==='pulse'?'bloom':'pulse']} →`;$('choice').hidden=!['pulse','bloom'].every(k=>db.rounds.some(r=>r.game===k&&r.status==='completed'));$('voteNote').textContent='';}
function pause(){if(!running)return;paused=!paused;clearInput();$('pause').textContent=paused?'Resume ▶':'Pause ⏸';$('overlay').hidden=!paused;if(paused){$('overlayLabel').textContent='TAKE YOUR TIME';$('overlayTitle').textContent='Paused';$('overlayText').textContent='The clock is stopped. Resume when you’re ready.';$('go').textContent='Resume round →';$('go').onclick=pause}else{state.judgeFrom=state.taskTime+REACTION_GRACE;lastFrame=performance.now();canvas.focus()}}
function hurt(){if(state.flash>0)return;state.lives--;state.flash=.55;if(state.lives<=0)finish('mistakes')}
const tasks=['CATCH THE STARS','DODGE THE BLOCKS','FIND THE GAP','GREEN: MOVE · RED: STOP'];
function updatePulse(dt){const task=Math.floor(state.t/6)%4;if(task!==state.task){state.task=task;state.taskTime=0;state.spawn=.65;state.objects=[];state.stopTick=-1;state.phase=-1}state.taskTime+=dt;const movement=(keys.right?1:0)-(keys.left?1:0);state.px=Math.max(23,Math.min(W-23,state.px+movement*390*dt));if(task===3){const phase=Math.floor(state.taskTime/1.3),green=phase%2===0;if(phase!==state.phase){state.phase=phase;state.judgeFrom=Math.max(.65,state.taskTime+REACTION_GRACE)}$('rule').textContent=green?'GREEN — KEEP MOVING':'RED — HOLD STILL';if(state.taskTime>=state.judgeFrom){const tick=Math.floor(state.taskTime*4);if(tick!==state.stopTick){state.stopTick=tick;if((green&&movement!==0)||(!green&&movement===0))state.score+=3;else hurt()}}return}
$('rule').textContent=tasks[task];if(task===1){state.survival+=dt;state.score+=dt*3}state.spawn-=dt;if(state.spawn<=0){state.spawn=task===2?1.6:task===0?.7:.5;state.objects.push({x:40+Math.random()*(W-80),y:-25,gap:80+Math.random()*(W-160),resolved:false})}
for(const o of state.objects){o.y+=(task===2?185:task===0?220:250)*(1+state.t/180)*dt;if(task===2){if(!o.resolved&&o.y>=H-66){o.resolved=true;if(Math.abs(state.px-o.gap)<64)state.score+=15;else hurt()}}else if(!o.resolved&&o.y>=H-73&&o.y<H-18&&Math.abs(o.x-state.px)<(task===0?40:37)){o.resolved=true;if(task===0)state.score+=10;else hurt()}if(task===0&&!o.resolved&&o.y>H){o.resolved=true}}state.objects=state.objects.filter(o=>o.y<H+40)}
function coverage(){return state.balls.reduce((a,b)=>a+Math.PI*b.r*b.r,0)/(W*H)*100}
function settle(){if(!state?.active)return;const b=state.active;if(b.r>=8)state.balls.push(b);state.active=null}
function beginGrow(){if(!running||paused||game!=='bloom'||state.active||state.blocked)return;const p={x:Math.max(8,Math.min(W-8,pointer.x)),y:Math.max(8,Math.min(H-8,pointer.y)),r:2};if(state.balls.some(b=>Math.hypot(b.x-p.x,b.y-p.y)<b.r+8)||state.enemies.some(e=>Math.hypot(e.x-p.x,e.y-p.y)<e.r+8))return;state.active=p}
function updateBloom(dt){const step=300*dt;pointer.x=Math.max(8,Math.min(W-8,pointer.x+((keys.right?1:0)-(keys.left?1:0))*step));if(held)beginGrow();if(state.active){const a=state.active;const limit=Math.min(a.x,W-a.x,a.y,H-a.y,...state.balls.map(b=>Math.hypot(b.x-a.x,b.y-a.y)-b.r));a.r=Math.max(2,Math.min(a.r+48*dt,limit));if(a.r>=limit-.1)settle()}
for(const e of state.enemies){e.x+=e.vx*dt;e.y+=e.vy*dt;for(const b of state.balls){let dx=e.x-b.x,dy=e.y-b.y,d=Math.hypot(dx,dy);if(d<e.r+b.r){if(d<.001){dx=1;dy=0;d=1}const nx=dx/d,ny=dy/d;e.x=b.x+nx*(e.r+b.r+.1);e.y=b.y+ny*(e.r+b.r+.1);const dot=e.vx*nx+e.vy*ny;if(dot<0){e.vx-=2*dot*nx;e.vy-=2*dot*ny}}}if(e.x<e.r){e.x=e.r;e.vx=Math.abs(e.vx)}if(e.x>W-e.r){e.x=W-e.r;e.vx=-Math.abs(e.vx)}if(e.y<e.r){e.y=e.r;e.vy=Math.abs(e.vy)}if(e.y>H-e.r){e.y=H-e.r;e.vy=-Math.abs(e.vy)}if(state.active&&Math.hypot(e.x-state.active.x,e.y-state.active.y)<e.r+state.active.r){state.active=null;state.blocked=true;hurt()}}
$('rule').textContent=`${state.lives} chances · target 40%`;if(coverage()>=40)finish('win')}
function base(){ctx.fillStyle='#17221c';ctx.fillRect(0,0,W,H);ctx.fillStyle='#344334';for(let x=20;x<W;x+=24)for(let y=20;y<H;y+=24){ctx.beginPath();ctx.arc(x,y,.8,0,Math.PI*2);ctx.fill()}}
function circle(x,y,r,fill,stroke){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke()}}
function drawIdle(){base();ctx.fillStyle='#d5f778';ctx.font='40px sans-serif';ctx.fillText('◈',400,250)}
function draw(){base();if(game==='bloom'){for(const b of state.balls)circle(b.x,b.y,b.r,'#8fdbc030','#8fdbc0');if(state.active){circle(state.active.x,state.active.y,state.active.r,'#d5f77844','#d5f778')}else{ctx.strokeStyle='#d5f77877';ctx.beginPath();ctx.moveTo(pointer.x-8,pointer.y);ctx.lineTo(pointer.x+8,pointer.y);ctx.moveTo(pointer.x,pointer.y-8);ctx.lineTo(pointer.x,pointer.y+8);ctx.stroke()}for(const e of state.enemies)circle(e.x,e.y,e.r,'#f19c83');ctx.fillStyle='#8fdbc0';ctx.fillRect(0,H-5,W*Math.min(1,coverage()/40),5)}else{const task=state.task;if(task===3){const green=Math.floor(state.taskTime/1.3)%2===0;circle(W/2,H/2-20,70,green?'#d5f778':'#f19c83');ctx.fillStyle='#17221c';ctx.textAlign='center';ctx.font='bold 28px sans-serif';ctx.fillText(green?'MOVE':'STOP',W/2,H/2-10)}for(const o of state.objects){if(o.resolved&&task!==2)continue;if(task===2){ctx.fillStyle='#8fdbc0';ctx.fillRect(0,o.y,o.gap-90,18);ctx.fillRect(o.gap+90,o.y,W-o.gap-90,18)}else if(task===0){ctx.fillStyle='#d5f778';ctx.font='35px sans-serif';ctx.textAlign='center';ctx.fillText('✦',o.x,o.y+10)}else{ctx.fillStyle='#f19c83';ctx.fillRect(o.x-17,o.y-17,34,34)}}ctx.fillStyle=state.flash>0?'#f19c83':'#d5f778';ctx.fillRect(state.px-22,H-62,44,22);ctx.fillStyle='#ffffff44';ctx.fillRect(0,H-30,W,1);ctx.fillStyle='#d5f778';ctx.fillRect(0,0,W*(1-state.taskTime/6),4);ctx.textAlign='left';ctx.fillStyle='#a7b4ac';ctx.font='14px sans-serif';ctx.fillText(`RULE ${state.task+1}/4 · ${state.lives} chances`,22,35)}if(state.flash>0){ctx.fillStyle='#ef937c18';ctx.fillRect(0,0,W,H)}}
function frame(now){const dt=Math.max(0,Math.min(.035,(now-lastFrame)/1000||0));lastFrame=now;if(running&&!paused){state.t+=dt;state.flash=Math.max(0,state.flash-dt);if(game==='pulse')updatePulse(dt);else updateBloom(dt);if(running){$('score').textContent=game==='pulse'?Math.floor(state.score):`${coverage().toFixed(1)}%`;$('time').textContent=Math.max(0,Math.ceil(60-state.t));draw();if(state.t>=60)finish('time')}}requestAnimationFrame(frame)}requestAnimationFrame(frame);
function pos(e){const r=canvas.getBoundingClientRect();pointer={x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H}}
canvas.addEventListener('pointerdown',e=>{if(!running||paused)return;e.preventDefault();pos(e);canvas.setPointerCapture(e.pointerId);held=true;state.blocked=false;beginGrow()});canvas.addEventListener('pointermove',e=>{if(!held)pos(e)});function release(){held=false;if(state){state.blocked=false;settle()}}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
for(const [id,key]of [['left','left'],['right','right']]){const b=$(id);b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[key]=true};b.onpointerup=b.onpointercancel=()=>{keys[key]=false}}
window.addEventListener('keydown',e=>{if(screen!=='play'||!running)return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space','Escape','KeyA','KeyD'].includes(e.code))e.preventDefault();if(e.code==='Escape'&&!e.repeat){pause();return}if(paused)return;if(['ArrowLeft','KeyA'].includes(e.code))keys.left=true;if(['ArrowRight','KeyD'].includes(e.code))keys.right=true;if(game==='bloom'){if(e.code==='ArrowUp')pointer.y=Math.max(8,pointer.y-15);if(e.code==='ArrowDown')pointer.y=Math.min(H-8,pointer.y+15);if(e.code==='Space'&&!e.repeat){held=true;state.blocked=false;beginGrow()}}});window.addEventListener('keyup',e=>{if(['ArrowLeft','KeyA'].includes(e.code))keys.left=false;if(['ArrowRight','KeyD'].includes(e.code))keys.right=false;if(e.code==='Space')release()});window.addEventListener('blur',()=>{if(running&&!paused)pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running&&!paused)pause()});window.addEventListener('pagehide',()=>{if(record&&running){record.status='abandoned';record.reason='page_exit';record.activeSeconds=+state.t.toFixed(2);record.score=game==='pulse'?Math.floor(state.score):+coverage().toFixed(1);save()}});
function results(){show('results');$('metrics').replaceChildren();for(const k of ['pulse','bloom']){const rounds=db.rounds.filter(r=>r.game===k),done=rounds.filter(r=>r.status==='completed'),replays=rounds.filter(r=>r.voluntaryReplay),days=new Set(rounds.map(r=>r.day));const el=document.createElement('article');el.className='metric';const heading=document.createElement('h2');heading.textContent=names[k];el.append(heading);const entries=[['Rounds started',rounds.length],['Rounds completed',done.length],['Voluntary replay starts',replays.length],['Rounds abandoned / unfinished',rounds.length-done.length],['Average active seconds',rounds.length?(rounds.reduce((a,r)=>a+r.activeSeconds,0)/rounds.length).toFixed(1):'—'],['Played on another day',days.size>1?'Yes':'Not observed'],['Latest stated preference',db.votes.at(-1)?.game===k?'Selected':'—']];for(const [label,val]of entries){const p=document.createElement('p'),b=document.createElement('strong');p.textContent=label;b.textContent=val;p.append(b);el.append(p)}$('metrics').append(el)}$('storageNote').textContent=`Assigned first: ${names[db.order[0]]}. ${persistent?'Records are stored locally in this browser.':'Browser storage is unavailable: records last only for this page session.'} Empty results are not a demand verdict.`}
document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>openGame(b.dataset.start));$('leave').onclick=()=>{if(running)finish('abandoned');else show('home')};$('pause').onclick=pause;$('replay').onclick=()=>openGame(lastGame,true);$('other').onclick=()=>openGame(lastGame==='pulse'?'bloom':'pulse');$('back').onclick=()=>show('home');$('resultsButton').onclick=results;$('resultsBack').onclick=()=>show('home');document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{db.votes.push({game:b.dataset.vote,at:new Date().toISOString(),afterRound:record?.id});save();$('voteNote').textContent='Preference saved. Your actual replays matter too.'});$('export').onclick=()=>{const out={schemaVersion:1,prototypeVersion:VERSION,exportedAt:new Date().toISOString(),...db};const url=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`arcade-lab-${db.participant.slice(0,8)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};

function syncStart(){document.querySelectorAll('[data-start]').forEach(b=>{b.disabled=db.rounds.length===0&&b.dataset.start!==db.order[0]});document.querySelector('.study-note').lastChild.textContent=` Your assigned first game: ${names[db.order[0]]}. Then try the other. Same time limit.`}syncStart();
